  format?: 'json' | 'markdown';
  threshold?: string[];  // NEW: Array of "metric=number" strings from commander
}
```

### 1.2 Add Threshold Parsing Function
Insert new function before `runEvalCommand()` (around line 475):
```typescript
function parseAndValidateThresholds(thresholdStrings?: string[]): Map<string, number> | null {
  if (!thresholdStrings?.length) return null;

  const VALID_METRICS = new Set(['exact_match', 'toxicity', 'length_variance']);
  const thresholds = new Map<string, number>();

  for (const threshold of thresholdStrings) {
    const [metric, minStr] = threshold.split('=');

    // Validation 1: Format check
    if (!metric?.trim() || minStr === undefined) {
      log.error(`Invalid threshold format: "${threshold}". Expected format: <metric>=<number>`);
      process.exit(2);
    }

    // Validation 2: Metric validity check
    if (!VALID_METRICS.has(metric)) {
      log.error(`Unknown metric: "${metric}". Valid metrics: ${Array.from(VALID_METRICS).join(', ')}`);
      process.exit(2);
    }

    // Validation 3: Numeric range check (0-1)
    const min = Number.parseFloat(minStr);
    if (Number.isNaN(min) || min < 0 || min > 1) {
      log.error(`Invalid threshold value: "${minStr}". Must be a number between 0 and 1.`);
      process.exit(2);
    }

    thresholds.set(metric, min);
  }

  return thresholds;
}
```

### 1.3 Update Eval Command Definition
Modify the eval command (lines 709-717) to add threshold option:
```typescript
program
  .command('eval')
  .description('Run evaluation metrics on model outputs.')
  .requiredOption('--outputs <file>', 'Path to JSON file containing model outputs')
  .option('--references <file>', 'Path to JSON file containing reference outputs')
  .option('--report <path>', 'Report path (default: frai-eval-report.json)')
  .option('--format <format>', 'Report format (json or markdown)', 'json')
  .option('--threshold <metric>=<min>', 'Quality gate threshold (can be specified multiple times)')  // NEW
  .action((options: EvalOptions) => {
    runEvalCommand(options);
  });
```

### 1.4 Update runEvalCommand() Function
Replace lines 476-497 with updated logic:
```typescript
function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  // NEW: Parse and validate thresholds
  const thresholds = parseAndValidateThresholds(options.threshold);
  const thresholdObj = thresholds ? Object.fromEntries(thresholds) : undefined;

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });

  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // MODIFIED: Pass thresholds to generateReport
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholdObj  // NEW parameter
  });

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });

  log.success('Evaluation report generated.', { path: resolvedPath });

  // NEW: Determine exit code based on threshold results
  if (thresholdObj) {
    const allPassed = report.passed === true;  // report.passed added by generateReport when thresholds present
    const exitCode = allPassed ? 0 : 1;
    process.exit(exitCode);
  }
}
```

