## Phase 2: Report Generation Logic (frai-core SDK)

**File**: `/packages/frai-core/src/eval/index.js`

### 2.1 Add Helper Function
Insert before `generateReport()` function (around line 61):
```javascript
function computeThresholdResults(evaluations, thresholds) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return undefined;
  }

  return Object.entries(thresholds).map(([metricId, minValue]) => {
    const metric = evaluations.find(m => m.id === metricId);

    if (!metric) {
      // Metric not found in evaluations (validation should prevent this)
      return {
        metric: metricId,
        min: minValue,
        score: null,
        passed: false
      };
    }

    const score = metric.score;
    // Key requirement: metric with score=null (no data) always fails its threshold
    const passed = score !== null && score >= minValue;

    return {
      metric: metricId,
      min: minValue,
      score: score ?? null,
      passed
    };
  });
}
```

### 2.2 Update generateReport() Function
Replace lines 62-82 with:
```javascript
export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = {},  // NEW: Optional object like { exact_match: 0.9, toxicity: 0.95 }
  generatedAt = new Date().toISOString()
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  // NEW: Compute threshold results if provided
  const thresholdResults = computeThresholdResults(evaluations, thresholds);
  const reportPassed = !thresholdResults || thresholdResults.every(t => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // NEW: Only add thresholds and passed fields if thresholds were provided
  if (thresholdResults) {
    report.thresholds = thresholdResults;
    report.passed = reportPassed;
  }

  return report;
}
```

