**File**: `/packages/frai-core/src/eval/index.test.js`

### 4.1 Add New Test Suite
Append to test file after existing tests:
```javascript
describe('Threshold evaluation', () => {
  it('computes thresholds correctly when all pass', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.5,
        toxicity: 0.8
      }
    });

    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds.every(t => t.passed)).toBe(true);
    expect(report.passed).toBe(true);
  });

  it('computes thresholds correctly when some fail', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['goodbye']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: {
        exact_match: 0.5  // Will fail because score is 0
      }
    });

    expect(report.thresholds[0].passed).toBe(false);
    expect(report.passed).toBe(false);
  });

  it('fails metric with null score against threshold', () => {
    const evaluations = [{
      id: 'exact_match',
      label: 'Exact Match',
      score: null,
      total: 0
    }];

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: { exact_match: 0 }
    });

    expect(report.thresholds[0].passed).toBe(false);
    expect(report.thresholds[0].score).toBeNull();
  });

  it('omits thresholds and passed fields when not provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json'
    });

    expect(report.thresholds).toBeUndefined();
    expect(report.passed).toBeUndefined();
  });

  it('includes formatted thresholds in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: {
        exact_match: 0.5
      }
    });

    const markdown = toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('exact_match');
    expect(markdown).toContain('PASS');
    expect(markdown).toContain('min: 0.5');
  });

  it('displays FAIL status in markdown when threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['goodbye']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      thresholds: {
        exact_match: 0.9
      }
    });

    const markdown = toMarkdown(report);
    expect(markdown).toContain('FAIL');
  });
});
```

