function computeThresholdResults(evaluations, thresholds) {
  if (!thresholds || Object.keys(thresholds).length === 0) {
    return undefined;
  }

  return Object.entries(thresholds).map(([metricId, minValue]) => {
    const metric = evaluations.find((m) => m.id === metricId);

    if (!metric) {
      return {
        metric: metricId,
        min: minValue,
        score: null,
        passed: false
      };
    }

    const score = metric.score;
    const passed = score !== null && score >= minValue;

    return {
      metric: metricId,
      min: minValue,
      score: score ?? null,
      passed
    };
  });
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = computeThresholdResults(evaluations, thresholds);
  const reportPassed = !thresholdResults || thresholdResults.every((t) => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults) {
    report.thresholds = thresholdResults;
    report.passed = reportPassed;
  }

  return report;
}

